examples/browser_app/main.py<pre><code>"""A small shop rendered on the server, for browsers: a session cookie, CSRF protection and the
security headers.

    uvicorn examples.browser_app.main:app

Then open http://localhost:8000 and sign in as "ana", password "correct horse battery staple".
The cookies are Secure; browsers accept them from http://localhost, which they treat as secure.

- `ServerSessionMiddleware` keeps each session (who signed in, the cart) in the cache's backend;
  the cookie only carries a random id. Signing in gives a new id, signing out deletes the
  session, and 30 minutes without requests end it.
- `CSRFMiddleware` refuses what pages on other sites make the browser send. With
  `require_token=True` it also wants the page's token in the `X-CSRF-Token` header: app.js sends
  the forms with it.
- `SecurityHeadersMiddleware` adds the security headers, with a Content-Security-Policy that only
  lets the pages run the app's own script; `BodySizeLimitMiddleware` refuses large bodies.

The sessions live in memory here; in production, in Redis or Valkey, so that every process sees
them, and a sign-out at once. Set SESSION_SIGNING_KEY (secrets.token_urlsafe(32)), in the
environment or a .env file.
"""

import hashlib
import hmac
import secrets
from collections.abc import AsyncIterator
from contextlib import asynccontextmanager
from enum import StrEnum
from html import escape
from typing import Annotated

import uvicorn
from fastapi import Depends, FastAPI, Form, Request
from fastapi.responses import HTMLResponse, RedirectResponse, Response
from pydantic import Field, SecretStr
from pydantic_settings import BaseSettings, SettingsConfigDict
from starlette.concurrency import run_in_threadpool

from fastapi_alcazaba import FastAPICache, FastAPIRateLimiter
from fastapi_alcazaba.backends.inmemory import InMemoryBackend
from fastapi_alcazaba.security import (
    BodySizeLimitMiddleware,
    CSRFMiddleware,
    SecurityHeadersMiddleware,
    ServerSessionMiddleware,
    clear_session,
    rotate_session,
)

# Only the app's own script, styles and images; no plugins, no framing, forms only to the app.
CSP = "default-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'"

APP_JS = """\
// Sends the forms with fetch, adding the CSRF token in the header that CSRFMiddleware checks:
// a plain form can't set headers.
const token = document.querySelector('meta[name="csrf-token"]').content;
for (const form of document.querySelectorAll("form[method=post]")) {
  form.addEventListener("submit", async (event) =&gt; {
    event.preventDefault();
    const response = await fetch(form.action, {
      method: "POST",
      headers: {"X-CSRF-Token": token},
      body: new URLSearchParams(new FormData(form)),
    });
    if (response.redirected) location.assign(response.url);
    else alert(`Refused: ${response.status} ${response.statusText}`);
  });
}
"""


class Product(StrEnum):
    # An enum: the cart only holds what the shop sells, so sessions stay small.
    OLIVE_OIL = "Olive oil"
    ALMONDS = "Almonds"
    FIGS = "Figs"


def scrypt(password: str, salt: bytes) -&gt; bytes:
    return hashlib.scrypt(password.encode(), salt=salt, n=2**14, r=8, p=1)


class Users:
    """Stands in for the users table: a salt and a slow hash of each password, never the
    password itself."""

    def __init__(self) -&gt; None:
        salt = secrets.token_bytes(16)
        self.rows = {"ana": (salt, scrypt("correct horse battery staple", salt))}

    def check(self, username: str, password: str) -&gt; bool:
        # Hashed for unknown users too: the time it takes doesn't tell who has an account.
        salt, stored = self.rows.get(username, (b"\0" * 16, b""))
        return hmac.compare_digest(scrypt(password, salt), stored)


users = Users()


def throwaway_secret() -&gt; SecretStr:
    """A random secret, for trying the example: it changes at every start and differs between
    processes."""
    return SecretStr(secrets.token_urlsafe(32))


class Settings(BaseSettings):
    """The configuration, from environment variables or a .env file."""

    model_config = SettingsConfigDict(env_file=".env", env_file_encoding="utf-8", extra="ignore")

    session_signing_key: SecretStr = Field(default_factory=throwaway_secret)


settings = Settings()


@asynccontextmanager
async def lifespan(_: FastAPI) -&gt; AsyncIterator[None]:
    # Redis or Valkey in production. Signed: whoever can write to the backend can't forge a
    # session (encryption_key instead, with the crypto extra, if they hold personal data).
    FastAPICache.init(InMemoryBackend(), prefix="shop", signing_key=settings.session_signing_key)
    yield


# No /docs: a site doesn't need them, and their CDN scripts wouldn't pass the CSP.
app = FastAPI(lifespan=lifespan, docs_url=None, redoc_url=None, openapi_url=None)
# Each middleware added wraps the ones before it: the first is the innermost.
app.add_middleware(
    ServerSessionMiddleware,
    max_age=8 * 3600,
    idle_timeout=30 * 60,
)
app.add_middleware(CSRFMiddleware, require_token=True)  # outside: refusals don't read sessions
app.add_middleware(BodySizeLimitMiddleware, max_size=64 * 1024)  # forms are small
# The outermost: the refusals of the middlewares inside it get the headers too.
app.add_middleware(SecurityHeadersMiddleware, html_csp=CSP)


def page(request: Request, body: str) -&gt; HTMLResponse:
    """The page around `body`, with the CSRF token for app.js."""
    token = escape(request.state.csrf_token)
    return HTMLResponse(
        '&lt;!doctype html&gt;&lt;html lang="en"&gt;&lt;head&gt;&lt;meta charset="utf-8"&gt;&lt;title&gt;Shop&lt;/title&gt;'
        f'&lt;meta name="csrf-token" content="{token}"&gt;&lt;script src="/app.js" defer&gt;&lt;/script&gt;'
        f"&lt;/head&gt;&lt;body&gt;{body}&lt;/body&gt;&lt;/html&gt;"
    )


def form(action: str, button: str, **fields: str) -&gt; str:
    inputs = "".join(
        f'&lt;input type="hidden" name="{name}" value="{escape(value)}"&gt;'
        for name, value in fields.items()
    )
    return f'&lt;form method="post" action="{action}"&gt;{inputs}&lt;button&gt;{button}&lt;/button&gt;&lt;/form&gt;'


@app.get("/")
async def home(request: Request) -&gt; HTMLResponse:
    user = request.session.get("user")
    if user is None:
        header = '&lt;p&gt;&lt;a href="/login"&gt;Sign in&lt;/a&gt;&lt;/p&gt;'
    else:
        header = f"&lt;p&gt;Signed in as {escape(user)}.&lt;/p&gt;{form('/logout', 'Sign out')}"
    products = "".join(
        f"&lt;li&gt;{escape(product)} {form('/cart', 'Add to cart', product=product)}&lt;/li&gt;"
        for product in Product
    )
    cart = request.session.get("cart", {})
    items = "".join(f"&lt;li&gt;{escape(p)}: {cart[p]}&lt;/li&gt;" for p in Product if p in cart)
    return page(request, f"{header}&lt;h1&gt;Shop&lt;/h1&gt;&lt;ul&gt;{products}&lt;/ul&gt;&lt;h2&gt;Cart&lt;/h2&gt;&lt;ul&gt;{items}&lt;/ul&gt;")


@app.get("/login")
async def login_page(request: Request, failed: bool = False) -&gt; HTMLResponse:
    error = "&lt;p&gt;Wrong username or password.&lt;/p&gt;" if failed else ""
    return page(
        request,
        f"&lt;h1&gt;Sign in&lt;/h1&gt;{error}"
        '&lt;form method="post" action="/login"&gt;'
        '&lt;label&gt;Username &lt;input name="username" autocomplete="username" required&gt;&lt;/label&gt; '
        '&lt;label&gt;Password &lt;input name="password" type="password" '
        'autocomplete="current-password" required&gt;&lt;/label&gt; &lt;button&gt;Sign in&lt;/button&gt;&lt;/form&gt;',
    )


# Five attempts a minute per client address.
@app.post("/login", dependencies=[Depends(FastAPIRateLimiter(times=5, minutes=1))])
async def login(
    request: Request,
    username: Annotated[str, Form(max_length=100)],
    password: Annotated[str, Form(max_length=200)],
) -&gt; RedirectResponse:
    # In a thread: scrypt is slow on purpose, and would hold up the other requests.
    if not await run_in_threadpool(users.check, username, password):
        return RedirectResponse("/login?failed=true", status_code=303)
    request.session["user"] = username
    rotate_session(request)  # a new id: one planted in the browser before is worthless now
    return RedirectResponse("/", status_code=303)


@app.post("/logout")
async def logout(request: Request) -&gt; RedirectResponse:
    clear_session(request)  # deleted from the backend: a copied cookie is worth nothing now
    return RedirectResponse("/", status_code=303)


@app.post("/cart")
async def add_to_cart(request: Request, product: Annotated[Product, Form()]) -&gt; RedirectResponse:
    cart = request.session.setdefault("cart", {})
    cart[product.value] = min(cart.get(product.value, 0) + 1, 10)  # at most 10 of each
    return RedirectResponse("/", status_code=303)


@app.get("/app.js")
async def script() -&gt; Response:
    return Response(APP_JS, media_type="text/javascript")


if __name__ == "__main__":
    uvicorn.run("main:app", reload=True)
</code></pre>

examples/passkeys/main.py<pre><code>"""A site without passwords: people sign up and log in with a passkey, see the devices they're
logged in on, and log them out.

    uvicorn examples.passkeys.main:app

Open http://localhost:8000 in a browser with passkeys (Chrome, Safari, Edge, Firefox): its page
signs up with a username and a passkey (Touch ID, Windows Hello, a phone, a security key), then
logs in with it, without typing anything. `/sessions` lists the devices of the user, each of
which `DELETE /sessions/{ref}` logs out, and `/sessions/end-all` all of them but this one.
Deleting the account needs a passkey of the last five minutes.

Set CACHE_SIGNING_KEY (`secrets.token_urlsafe(32)`), the same in every process; WEBAUTHN_RP_ID
and WEBAUTHN_ORIGIN for another site than localhost.
"""

import secrets
import uuid
from collections.abc import AsyncIterator
from contextlib import asynccontextmanager
from typing import Annotated, Any

import uvicorn
from fastapi import Depends, FastAPI, HTTPException, Request, status
from fastapi.responses import HTMLResponse
from pydantic import BaseModel, Field, SecretStr
from pydantic_settings import BaseSettings, SettingsConfigDict

from fastapi_alcazaba import FastAPICache, FastAPIWebAuthn
from fastapi_alcazaba.auth import Passkey, WebAuthnRefused, credential_id
from fastapi_alcazaba.backends.inmemory import InMemoryBackend
from fastapi_alcazaba.security import (
    CSRFMiddleware,
    ServerSessionMiddleware,
    UserSessions,
    clear_session,
    rotate_session,
)


def throwaway_secret() -&gt; SecretStr:
    """A random secret, for trying the example: it changes at every start and differs between
    processes."""
    return SecretStr(secrets.token_urlsafe(32))


class Settings(BaseSettings):
    """The configuration, from environment variables or a .env file."""

    model_config = SettingsConfigDict(env_file=".env", env_file_encoding="utf-8", extra="ignore")

    webauthn_rp_id: str = "localhost"
    webauthn_origin: str = "http://localhost:8000"
    cache_signing_key: SecretStr = Field(default_factory=throwaway_secret)


settings = Settings()


class User(BaseModel):
    id: str
    username: str
    handle: str  # the WebAuthn user handle: random, the same for all their passkeys
    passkeys: list[dict[str, Any]] = []  # Passkey.to_dict(): public keys, nothing secret


class Database:
    """Stands in for the database."""

    def __init__(self) -&gt; None:
        self.users: dict[str, User] = {}
        self.owners: dict[str, str] = {}  # credential id -&gt; user id

    def by_name(self, username: str) -&gt; User | None:
        return next((user for user in self.users.values() if user.username == username), None)


class SignUp(BaseModel):
    username: str = Field(pattern=r"^[a-z0-9_]{3,30}$")


db = Database()
webauthn = FastAPIWebAuthn(
    rp_id=settings.webauthn_rp_id,
    rp_name="Example",
    origins=[settings.webauthn_origin],
)
user_sessions = UserSessions()


def current_user(request: Request) -&gt; User:
    user = db.users.get(request.session.get("user_id", ""))
    if user is None:
        raise HTTPException(status.HTTP_401_UNAUTHORIZED, "Not logged in")
    return user


def current_user_id(request: Request) -&gt; str | None:
    return request.session.get("user_id")


CurrentUser = Annotated[User, Depends(current_user)]


def log_in(request: Request, user: User) -&gt; dict[str, str]:
    """The session is the user's from now on, and its passkey a recent second factor."""
    request.session.clear()
    request.session["user_id"] = user.id
    rotate_session(request)  # no session fixation
    webauthn.mark(request, user.id)  # a verified passkey: both factors at once
    return {"logged_in": user.username}


@asynccontextmanager
async def lifespan(_: FastAPI) -&gt; AsyncIterator[None]:
    # Redis or Valkey in production: the challenges and the sessions, shared by every process.
    FastAPICache.init(InMemoryBackend(), prefix="passkeys", signing_key=settings.cache_signing_key)
    yield


app = FastAPI(lifespan=lifespan)
app.add_middleware(ServerSessionMiddleware, users=user_sessions, max_age=8 * 3600)
app.add_middleware(CSRFMiddleware)  # session cookies: refuse what other sites make browsers send


@app.post("/signup/options")
async def sign_up_options(request: Request, form: SignUp) -&gt; dict[str, Any]:
    """The options for the browser to make a passkey for a new user, kept pending until it does."""
    if db.by_name(form.username) is not None:
        raise HTTPException(status.HTTP_409_CONFLICT, "That username is taken")
    user_id = uuid.uuid4().hex
    options = await webauthn.registration_options(user_id, form.username)
    request.session["signing_up"] = {
        "id": user_id,
        "username": form.username,
        "handle": options["user"]["id"],
    }
    return options


@app.post("/signup")
async def sign_up(request: Request, credential: dict[str, Any]) -&gt; dict[str, str]:
    """The passkey the browser made: the user exists from now on, and is logged in."""
    pending = request.session.get("signing_up")
    if pending is None:
        raise HTTPException(status.HTTP_400_BAD_REQUEST, "Ask for the options first")
    try:
        passkey = await webauthn.verify_registration(pending["id"], credential, request=request)
    except WebAuthnRefused:
        raise HTTPException(status.HTTP_400_BAD_REQUEST, "That passkey wasn't accepted") from None
    if passkey.id in db.owners:
        raise HTTPException(status.HTTP_409_CONFLICT, "That passkey is someone else's")
    user = User(**pending, passkeys=[passkey.to_dict()])
    db.users[user.id] = user
    db.owners[passkey.id] = user.id
    return log_in(request, user)


def find_passkey(passkey_id: str) -&gt; tuple[User, Passkey]:
    """The passkey the browser answered with, and its user."""
    owner = db.users.get(db.owners.get(passkey_id, ""))
    for stored in owner.passkeys if owner is not None else []:
        if stored["id"] == passkey_id:
            return owner, Passkey.from_dict(stored)  # type: ignore[return-value]
    raise WebAuthnRefused("unknown", "no such passkey")


@app.post("/login/options")
async def login_options() -&gt; dict[str, Any]:
    """The options for any passkey of this site: the browser asks which one."""
    return await webauthn.authentication_options()


@app.post("/login")
async def login(request: Request, credential: dict[str, Any]) -&gt; dict[str, str]:
    """A passkey's answer: its user is logged in."""
    try:
        owner, passkey = find_passkey(credential_id(credential))
        updated = await webauthn.verify_authentication(
            credential, passkey, user_id=owner.id, request=request
        )
    except WebAuthnRefused:
        raise HTTPException(status.HTTP_401_UNAUTHORIZED, "That passkey wasn't accepted") from None
    owner.passkeys = [updated.to_dict() if p["id"] == updated.id else p for p in owner.passkeys]
    return log_in(request, owner)


@app.get("/me")
async def me(user: CurrentUser) -&gt; dict[str, Any]:
    return {"username": user.username, "passkeys": len(user.passkeys)}


@app.get("/sessions")
async def sessions(request: Request, user: CurrentUser) -&gt; list[dict[str, Any]]:
    """The devices the user is logged in on, the newest first."""
    found = await user_sessions.list(user.id, request=request)
    return [
        {
            "ref": session.ref,
            "since": session.created.isoformat(),
            "last_seen": session.last_seen.isoformat(),
            "device": session.user_agent,
            "this_one": session.current,
        }
        for session in found
    ]


@app.delete("/sessions/{ref}", status_code=status.HTTP_204_NO_CONTENT)
async def end_session(request: Request, ref: str, user: CurrentUser) -&gt; None:
    """Log one of the user's devices out."""
    if not await user_sessions.end(user.id, ref, request=request):
        raise HTTPException(status.HTTP_404_NOT_FOUND, "No such session")


@app.post("/sessions/end-all")
async def end_all_sessions(request: Request, user: CurrentUser) -&gt; dict[str, int]:
    """Log every other device out: a lost phone, a shared computer."""
    ended = await user_sessions.end_all(user.id, request=request, keep_current=True)
    return {"ended": ended}


@app.post("/logout", status_code=status.HTTP_204_NO_CONTENT)
async def logout(request: Request) -&gt; None:
    clear_session(request)


@app.delete(
    "/account",
    status_code=status.HTTP_204_NO_CONTENT,
    dependencies=[Depends(webauthn.require_recent(current_user_id, max_age=300))],
)
async def delete_account(request: Request, user: CurrentUser) -&gt; None:
    """Needs a passkey of the last five minutes: a session left open isn't enough."""
    await user_sessions.end_all(user.id, request=request)
    for passkey in user.passkeys:
        db.owners.pop(passkey["id"], None)
    del db.users[user.id]
    clear_session(request)


@app.get("/", response_class=HTMLResponse)
async def page() -&gt; str:
    return PAGE


PAGE = """&lt;!doctype html&gt;
&lt;html lang="en"&gt;
&lt;meta charset="utf-8"&gt;
&lt;title&gt;Passkeys&lt;/title&gt;
&lt;h1&gt;Passkeys&lt;/h1&gt;
&lt;p&gt;&lt;input id="username" placeholder="username"&gt; &lt;button id="signup"&gt;Sign up&lt;/button&gt;
&lt;p&gt;&lt;button id="login"&gt;Log in with a passkey&lt;/button&gt;
&lt;pre id="out"&gt;&lt;/pre&gt;
&lt;script&gt;
const out = document.getElementById("out");
async function post(path, body) {
  const response = await fetch(path, {
    method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify(body),
  });
  const answer = await response.json();
  if (!response.ok) throw new Error(answer.detail);
  return answer;
}
document.getElementById("signup").onclick = async () =&gt; {
  try {
    const username = document.getElementById("username").value;
    const options = await post("/signup/options", {username});
    const credential = await navigator.credentials.create(
      {publicKey: PublicKeyCredential.parseCreationOptionsFromJSON(options)});
    out.textContent = JSON.stringify(await post("/signup", credential.toJSON()));
  } catch (error) { out.textContent = error; }
};
document.getElementById("login").onclick = async () =&gt; {
  try {
    const options = await post("/login/options", {});
    const credential = await navigator.credentials.get(
      {publicKey: PublicKeyCredential.parseRequestOptionsFromJSON(options)});
    out.textContent = JSON.stringify(await post("/login", credential.toJSON()));
  } catch (error) { out.textContent = error; }
};
&lt;/script&gt;
"""


if __name__ == "__main__":
    uvicorn.run("main:app", reload=True)
</code></pre>

examples/authz/policies.cedar<pre><code>// Everybody with an account lists the documents; each one is checked as it's read.
permit (principal, action == Action::"GET", resource == Resource::"/documents");

// The members of a document's team read it.
permit (principal, action == Action::"read", resource)
when { principal.team == resource.team };

// Its owner reads and edits it.
permit (principal, action in [Action::"read", Action::"edit"], resource)
when { resource.owner == principal };

// Admins delete documents.
permit (
  principal in Role::"admin",
  action == Action::"delete",
  resource == Resource::"documents"
);

// Contractors never see a confidential document, whatever else allows it.
forbid (principal, action, resource)
when { principal.contractor &amp;&amp; resource is Document &amp;&amp; resource.confidential };
</code></pre> examples/authz/schema.cedarschema<pre><code>entity Role;
entity User in [Role] { team: String, contractor: Bool };
entity Document { owner: User, team: String, confidential: Bool };
entity Resource { id: String };

action read, edit appliesTo { principal: [User], resource: [Document] };
action GET, delete appliesTo { principal: [User], resource: [Resource] };
</code></pre> examples/authz/cedar_policies.py<pre><code>"""A team's shared documents, whose Cedar policies decide who reads, edits and deletes each one by
its attributes: its team, its owner, whether it's confidential, and who's asking.

    uvicorn examples.authz.cedar_policies:app

The members of a document's team read it, its owner edits it, admins delete documents, and
contractors never see a confidential one, whatever else allows it: a `forbid` beats every
`permit`. The policies are in policies.cedar, validated at start against schema.cedarschema.
The user (with its team and roles) is the entity the authentication gives; each document, the
entity the route builds from the row it read.
"""

from pathlib import Path
from typing import Annotated, Any

import uvicorn
from fastapi import Depends, FastAPI, HTTPException, status
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from pydantic import BaseModel, Field

from fastapi_alcazaba.authz import FastAPIAuthz
from fastapi_alcazaba.authz.cedar import CedarEnforcer

HERE = Path(__file__).parent


class Document(BaseModel):
    id: int
    title: str = Field(max_length=200)
    owner: str
    team: str
    confidential: bool = False


class Edit(BaseModel):
    title: str = Field(max_length=200)


class User(BaseModel):
    name: str
    team: str
    contractor: bool = False
    roles: list[str] = []


class Database:
    """Stands in for the database."""

    def __init__(self) -&gt; None:
        self.documents = {
            1: Document(id=1, title="Style guide", owner="ana", team="editorial"),
            2: Document(
                id=2, title="Budget 2027", owner="ben", team="editorial", confidential=True
            ),
            3: Document(id=3, title="Sales targets", owner="dan", team="sales"),
        }


db = Database()
bearer = HTTPBearer(auto_error=False)
# Stands in for the app's authentication (JWTs, sessions, API keys): a token per user.
USERS = {
    "ana-token": User(name="ana", team="editorial", roles=["admin"]),
    "ben-token": User(name="ben", team="editorial"),
    "eva-token": User(name="eva", team="editorial", contractor=True),
    "dan-token": User(name="dan", team="sales"),
}


def user_entity(user: User) -&gt; dict[str, Any]:
    """The user as Cedar sees it: its attributes, and its roles as parents."""
    return {
        "uid": {"type": "User", "id": user.name},
        "attrs": {"team": user.team, "contractor": user.contractor},
        "parents": [{"type": "Role", "id": role} for role in user.roles],
    }


def document_entity(document: Document) -&gt; dict[str, Any]:
    owner = {"__entity": {"type": "User", "id": document.owner}}
    attrs = {"owner": owner, "team": document.team, "confidential": document.confidential}
    return {"uid": {"type": "Document", "id": str(document.id)}, "attrs": attrs, "parents": []}


async def current_user(
    credentials: Annotated[HTTPAuthorizationCredentials | None, Depends(bearer)],
) -&gt; dict[str, Any] | None:
    """Who makes the request, as a Cedar entity; None without a token."""
    if credentials is None:
        return None
    user = USERS.get(credentials.credentials)
    if user is None:
        raise HTTPException(401, "Invalid token", headers={"WWW-Authenticate": "Bearer"})
    return user_entity(user)


enforcer = CedarEnforcer(
    (HERE / "policies.cedar").read_text(),
    entities=[{"uid": {"type": "Role", "id": "admin"}, "attrs": {}, "parents": []}],
    schema=(HERE / "schema.cedarschema").read_text(),  # the policies are checked against it
)
authz = FastAPIAuthz(enforcer, subject=current_user)  # a 401 without a token
Member = Annotated[dict[str, Any], Depends(authz)]  # (user, path, method): GET /documents


async def signed_in(
    user: Annotated[dict[str, Any] | None, Depends(current_user)],
) -&gt; dict[str, Any]:
    """The user, for routes that ask the policy about the document they read."""
    if user is None:
        raise HTTPException(401, "Not authenticated", headers={"WWW-Authenticate": "Bearer"})
    return user


SignedIn = Annotated[dict[str, Any], Depends(signed_in)]

app = FastAPI()


async def readable(user: dict[str, Any], document_id: int) -&gt; Document:
    """The document, if the user may read it; a 404 otherwise, as if it didn't exist."""
    document = db.documents.get(document_id)
    if document is None or not await authz.enforce(user, document_entity(document), "read"):
        raise HTTPException(404, "No such document")
    return document


@app.get("/documents")
async def list_documents(user: Member) -&gt; list[Document]:
    """Those the user may read: the policy decides for each one."""
    documents = db.documents.values()
    return [d for d in documents if await authz.enforce(user, document_entity(d), "read")]


@app.get("/documents/{document_id}")
async def read_document(document_id: int, user: SignedIn) -&gt; Document:
    return await readable(user, document_id)


@app.put("/documents/{document_id}")
async def edit_document(document_id: int, edit: Edit, user: SignedIn) -&gt; Document:
    document = await readable(user, document_id)
    if not await authz.enforce(user, document_entity(document), "edit"):
        raise HTTPException(403, "Only its owner edits a document")
    document.title = edit.title
    return document


@app.delete(
    "/documents/{document_id}",
    status_code=status.HTTP_204_NO_CONTENT,
    dependencies=[Depends(authz.require("documents", "delete"))],
)
async def delete_document(document_id: int) -&gt; None:
    """A named action, not a path: (user, documents, delete)."""
    if db.documents.pop(document_id, None) is None:
        raise HTTPException(404, "No such document")


if __name__ == "__main__":
    uvicorn.run("cedar_policies:app", reload=True)
